// Auto-generated for the Unit Board — AWL Sublist 9
window.A9_DASHBOARD_UNITS = [{"unit":1,"theme":"accommodate – on behalf of","cards":[{"w":"accommodate","p":"v.","d":"to have enough space for people or things","c":"容納","s":"The hall can accommodate up to 300 guests.","t":"這個大廳可以容納多達300名賓客。"},{"w":"accommodate","p":"v.","d":"to give people what they need","c":"照顧到，考慮","s":"We will accommodate your dietary restrictions during the dinner event.","t":"我們會在晚宴活動期間考慮您的飲食限制。"},{"w":"accommodation","p":"n.","d":"a place to stay or live","c":"住宿","s":"They booked their accommodation in advance to ensure a place to stay during the trip.","t":"他們提前預訂了住宿，以確保在旅行期間有地方住。"},{"w":"analogy","p":"n.","d":"a comparison that shows how two things are alike","c":"類比","s":"He made an analogy between the human heart and a pump to explain its function.","t":"他通過將人類的心臟和泵進行類比來解釋其功能。"},{"w":"analogous","p":"adj.","d":"similar in some way","c":"類似的","s":"The structure of an atom is somewhat analogous to that of a solar system.","t":"原子的結構在某程度上類似於太陽系的結構。"},{"w":"anticipate","p":"v.","d":"to expect something to happen","c":"預期","s":"We anticipate a high turnout for the event given the level of interest.","t":"鑑於興趣的程度，我們預期此次活動的參與人數會很高。"},{"w":"anticipated","p":"adj.","d":"expected","c":"預期的","s":"The anticipated challenges were well-managed by the team.","t":"團隊很好地管理了預期的挑戰。"},{"w":"anticipation","p":"n.","d":"the feeling of waiting for something exciting","c":"預期","s":"The anticipation for the new product release is building up.","t":"新產品發布的預期正在積聚。"},{"w":"assure","p":"v.","d":"to tell someone something is true so they don't worry","c":"保證","s":"I can assure you that your concerns will be addressed promptly.","t":"我可以保證您的疑慮將得到及時解決。"},{"w":"reassure","p":"v.","d":"to make someone feel less worried again","c":"再保證","s":"The manager tried to reassure the team after a series of losses.","t":"經理試圖在一系列失敗後再次保證團隊。"},{"w":"reassured","p":"adj.","d":"feeling less worried","c":"放心的","s":"She felt reassured after talking to the doctor about her symptoms.","t":"在與醫生談談她的症狀後，她感到放心。"},{"w":"assurance","p":"n.","d":"a promise that something is true or will happen","c":"保證","s":"His assurance of support gave us the confidence to proceed.","t":"他對支持的保證給了我們繼續的信心。"},{"w":"ensure","p":"v.","d":"to make sure something happens","c":"確保","s":"We need to ensure that all attendees have a clear understanding of the agenda.","t":"我們需要確保所有與會者對議程有清晰的理解。"},{"w":"insure","p":"v.","d":"to buy protection against loss or damage","c":"保險","s":"It's wise to insure your property against theft and damage.","t":"對防盜和損壞保險您的財產是明智的。"},{"w":"insurance","p":"n.","d":"money paid for protection against loss","c":"保險","s":"Health insurance can provide financial protection against medical expenses.","t":"健康保險可以提供對醫療費用的財務保護。"},{"w":"attain","p":"v.","d":"to reach or achieve something","c":"獲得","s":"With hard work, you can attain your goals.","t":"通過努力工作，您可以實現您的目標。"},{"w":"attained","p":"adj.","d":"reached or achieved","c":"達到的","s":"The attained level of success was beyond our expectations.","t":"達到的成功水平超出了我們的期望。"},{"w":"attainment","p":"n.","d":"the act of achieving something","c":"獲得","s":"His attainment in the field of physics is remarkable.","t":"他在物理領域的成就非常顯著。"},{"w":"behalf","p":"n.","d":"for someone else","c":"代表","s":"She spoke on behalf of the entire committee.","t":"她代表整個委員會發言。"},{"w":"on behalf of","p":"phr.","d":"speaking or acting for someone else","c":"代表","s":"He accepted the award on behalf of his team.","t":"他代表他的團隊接受了這個獎項。"}]},{"unit":2,"theme":"behave – current","cards":[{"w":"behave","p":"v.","d":"to act in a certain way","c":"表現","s":"Children are expected to behave well in public places.","t":"人們希望孩子們在公共場所表現得很好。"},{"w":"behavior","p":"n.","d":"the way someone acts","c":"行為","s":"His disruptive behavior was addressed by the teacher.","t":"他的破壞性行為得到了老師的解決。"},{"w":"in bulk","p":"phr.","d":"in large amounts","c":"大量","s":"Buying in bulk can save money in the long run.","t":"長期來看，大量購買可以節省資金。"},{"w":"cease","p":"v.","d":"to stop","c":"停止","s":"The rain will not cease until tomorrow.","t":"雨不會在明天之前停止。"},{"w":"ceaselessly","p":"adv.","d":"without stopping","c":"不停地","s":"She worked ceaselessly to meet the deadline.","t":"她不停地工作以趕上截止日期。"},{"w":"coherent","p":"adj.","d":"clear and logical","c":"連貫的","s":"His argument was coherent and well-structured.","t":"他的論點是連貫且結構良好的。"},{"w":"coherence","p":"n.","d":"the quality of being clear and logical","c":"連貫性","s":"The essay lacked coherence and was difficult to follow.","t":"這篇文章缺乏連貫性，很難理解。"},{"w":"coincide with","p":"v.","d":"to happen at the same time as something","c":"與...一致","s":"The results of the experiment coincide with our predictions.","t":"實驗的結果與我們的預測一致。"},{"w":"coincident","p":"adj.","d":"happening at the same time","c":"同時發生的","s":"The coincident events caused a lot of confusion among the attendees.","t":"同時發生的事件使與會者感到很困惑。"},{"w":"coincidence","p":"n.","d":"two things happening together by chance","c":"巧合","s":"It was a pure coincidence that we ran into each other at the mall.","t":"我們在商場相遇純屬巧合。"},{"w":"commence","p":"v.","d":"to begin","c":"開始","s":"The ceremony will commence at 10 a.m. sharp.","t":"儀式將在上午10點正式開始。"},{"w":"commencement","p":"n.","d":"the beginning of something; a graduation ceremony","c":"開始","s":"The commencement of the project is scheduled for next Monday.","t":"該項目的開始計劃在下周一。"},{"w":"commencement speech","p":"n.","d":"a speech given at a graduation ceremony","c":"開學演講","s":"The keynote speaker delivered an inspiring commencement speech.","t":"主題演講者發表了一篇鼓舞人心的開學演講。"},{"w":"compare","p":"v.","d":"to look at how things are alike or different","c":"比較","s":"It's difficult to compare the two products as they serve different purposes.","t":"由於這兩種產品具有不同的用途，因此很難將它們進行比較。"},{"w":"compatible","p":"adj.","d":"able to work well together","c":"相容的","s":"The software may not be compatible with older operating systems.","t":"該軟件可能與較舊的操作系統不兼容。"},{"w":"incompatible","p":"adj.","d":"not able to work well together","c":"不相容的","s":"Their differing values were incompatible, leading to frequent disagreements.","t":"他們不同的價值觀是不相容的，導致經常發生分歧。"},{"w":"current","p":"adj.","d":"happening now","c":"當前的","s":"The current economic conditions are favorable for investment.","t":"當前的經濟狀況有利於投資。"},{"w":"current trends","p":"n.","d":"the most recent and popular styles","c":"最新潮流、趨勢","s":"She always dresses according to the current trends.","t":"她總是依照最新的潮流穿著。"},{"w":"concurrent","p":"adj.","d":"happening at the same time","c":"同時的","s":"The concurrent development of multiple projects required careful coordination.","t":"多個項目的同時開發需要仔細協調。"},{"w":"current","p":"n.","d":"a flow of water in the sea or a river","c":"海洋或河流中的水流","s":"The swimmer was carried away by a strong current.","t":"那位游泳者被強烈的洋流沖走了。"}]},{"unit":3,"theme":"current – be devoted to","cards":[{"w":"current","p":"n.","d":"a flow of electricity","c":"電流","s":"Be careful not to touch the wire; it has an electric current.","t":"小心別碰到電線；它有電流。"},{"w":"currency","p":"n.","d":"the money used in a country","c":"一國使用的貨幣系統","s":"The country decided to change its currency.","t":"該國決定更換其貨幣。"},{"w":"currency exchange","p":"n.","d":"changing one country's money into another","c":"貨幣兌換","s":"We checked the currency exchange rates before our trip.","t":"我們在旅行前查了貨幣兌換匯率。"},{"w":"appreciation of currency","p":"n.","d":"a rise in the value of a currency","c":"貨幣升值","s":"The appreciation of currency made imports cheaper.","t":"貨幣升值讓進口商品變得更便宜。"},{"w":"depreciation of currency","p":"n.","d":"a fall in the value of a currency","c":"貨幣貶值","s":"The depreciation of currency caused prices of foreign goods to rise.","t":"貨幣貶值導致外國商品價格上升。"},{"w":"inflation","p":"n.","d":"a rise in prices over time","c":"物價上漲","s":"inflation affects the cost of everyday goods.","t":"通貨膨脹影響日常商品的價格。"},{"w":"deflation","p":"n.","d":"a fall in prices over time","c":"物價下降","s":"During deflation, people may spend less money.","t":"在通貨緊縮時期，人們可能會減少消費。"},{"w":"confine","p":"v.","d":"to keep something within limits","c":"限制","s":"Please confine your discussions to the topic at hand.","t":"請將您的討論限制在手頭的主題上。"},{"w":"confined","p":"adj.","d":"kept in a small space","c":"被限制的","s":"The prisoner was confined to his cell for 23 hours a day.","t":"囚犯每天被限制在牢房裡23個小時。"},{"w":"confinement","p":"n.","d":"being kept in a small space","c":"限制","s":"The confinement of the animals to small cages was criticized by the animal rights activists.","t":"動物權利活動家批評了將動物限制在小籠子裡。"},{"w":"controversy","p":"n.","d":"a public disagreement about something","c":"爭議","s":"The new policy sparked a lot of controversy among the stakeholders.","t":"新政策在利益相關者中引起了很多爭議。"},{"w":"controversial","p":"adj.","d":"causing a lot of disagreement","c":"有爭議的","s":"The controversial decision was discussed in all major news outlets.","t":"所有主要新聞媒體都討論了有爭議的決定。"},{"w":"converse","p":"v.","d":"to talk with someone","c":"談話","s":"They would converse for hours on end about various topics.","t":"他們會不停地談論各種話題。"},{"w":"the converse","p":"n.","d":"the opposite of something","c":"相反的事物","s":"The converse is also true under certain conditions.","t":"在某些條件下，相反的情況也是真的。"},{"w":"converse","p":"adj.","d":"opposite","c":"相反的","s":"In a converse scenario, the outcomes would be drastically different.","t":"在相反的情境下，結果將截然不同。"},{"w":"conversely","p":"adv.","d":"in an opposite way","c":"相反地","s":"conversely, if the conditions are not met, the project cannot proceed.","t":"相反地，如果條件未得到滿足，該項目無法繼續進行。"},{"w":"device","p":"n.","d":"a tool or machine for a special purpose","c":"裝置","s":"The device is designed to measure heart rate accurately.","t":"該裝置旨在準確測量心率。"},{"w":"devise","p":"v.","d":"to plan or invent something","c":"設計","s":"They managed to devise a plan to tackle the issue efficiently.","t":"他們設計了一個計劃以有效地解決這個問題。"},{"w":"devote to","p":"phr.","d":"to give your time and energy to something","c":"致力於","s":"She decided to devote to her life to helping others.","t":"她決定致力於幫助他人。"},{"w":"be devoted to","p":"phr.","d":"to give all your time and energy to something","c":"致力於","s":"He is devoted to his research and spends countless hours in the lab.","t":"他致力於他的研究並在實驗室裡花費無數的時間。"}]},{"unit":4,"theme":"devotion to – format","cards":[{"w":"devotion to","p":"phr.","d":"great love or loyalty to something","c":"致力於","s":"His devotion to his work is truly inspirational.","t":"他對工作的奉獻真的令人鼓舞。"},{"w":"dedicate to","p":"phr.","d":"to give your time and energy to something","c":"致力於","s":"The charity event is dedicate to raising funds for the local hospital.","t":"慈善活動致力於為當地醫院籌集資金。"},{"w":"be dedicated to","p":"phr.","d":"to give all your time and energy to something","c":"致力於","s":"The organization is dedicated to providing educational resources to underprivileged children.","t":"該組織致力於為弱勢兒童提供教育資源。"},{"w":"dedication to","p":"phr.","d":"hard work and loyalty to something","c":"致力於","s":"Her dedication to excellence is well-known in the industry.","t":"她對卓越的奉獻在行業中眾所周知。"},{"w":"commit to","p":"phr.","d":"to promise to do something","c":"承諾","s":"They commit to delivering the project on time.","t":"他們承諾按時交付該項目。"},{"w":"be committed to","p":"phr.","d":"to work very hard for something you believe in","c":"承諾","s":"The team is committed to achieving the set goals before the year ends.","t":"團隊致力於在年底前實現設定的目標。"},{"w":"make commitment to","p":"phr.","d":"to promise to give your support","c":"作出承諾","s":"They make commitment to uphold the highest standards in their services.","t":"他們作出承諾在他們的服務中堅持最高標準。"},{"w":"diminish","p":"v.","d":"to become smaller or weaker","c":"減少","s":"The resources will diminish if we do not implement conservation measures.","t":"如果我們不實施保護措施，資源將會減少。"},{"w":"diminished","p":"adj.","d":"made smaller or weaker","c":"減少的","s":"His influence has diminished over the years.","t":"他的影響力多年來已經減少了。"},{"w":"distort","p":"v.","d":"to change something so it is not true or clear","c":"扭曲","s":"Misleading information can distort the public's perception.","t":"誤導性的信息可能會扭曲公眾的認知。"},{"w":"distorted","p":"adj.","d":"changed so it is not true or clear","c":"扭曲的","s":"The image was distorted, making it hard to identify the details.","t":"圖像被扭曲，使得很難識別細節。"},{"w":"distortion","p":"n.","d":"a change that makes something untrue or unclear","c":"扭曲","s":"There's a lot of distortion in the way the media presents facts sometimes.","t":"媒體有時在呈現事實的方式上存在很多扭曲。"},{"w":"during","p":"prep.","d":"through the whole time of something","c":"在...期間","s":"She traveled extensively during her gap year.","t":"在她的空檔年期間，她廣泛旅行。"},{"w":"duration","p":"n.","d":"how long something lasts","c":"持續時間","s":"The duration of the course is 6 months.","t":"課程的持續時間是6個月。"},{"w":"erode","p":"v.","d":"to wear away slowly by wind or water","c":"侵蝕","s":"Water can erode soil over time, leading to land degradation.","t":"水可以隨著時間侵蝕土壤，導致土地退化。"},{"w":"erosive","p":"adj.","d":"slowly wearing something away","c":"侵蝕的","s":"The erosive effects of wind can cause soil loss.","t":"風的侵蝕效應可能會導致土壤流失。"},{"w":"erosion","p":"n.","d":"the slow wearing away of land","c":"侵蝕","s":"Soil erosion is a serious environmental issue.","t":"土壤侵蝕是一個嚴重的環境問題。"},{"w":"ethical","p":"adj.","d":"about right and wrong behavior","c":"倫理的","s":"It's important to make ethical decisions in business to maintain a good reputation.","t":"在商業中做出倫理決策以維護良好的聲譽非常重要。"},{"w":"format","p":"n.","d":"the way something is arranged","c":"格式","s":"The document needs to be saved in a specific format to be compatible with the software.","t":"該文檔需要以特定格式保存才能與軟件兼容。"},{"w":"format","p":"v.","d":"to arrange something in a certain way","c":"格式化","s":"You will need to format the hard drive before installing the new operating system.","t":"在安裝新操作系統之前，您需要格式化硬盤。"}]},{"unit":5,"theme":"informal – mediate","cards":[{"w":"informal","p":"adj.","d":"relaxed and friendly; not official","c":"非正式的","s":"The informal meeting allowed everyone to speak freely and share their ideas.","t":"非正式會議讓每個人都可以自由發言並分享他們的想法。"},{"w":"formal","p":"adj.","d":"official and serious","c":"正式的","s":"A formal dinner requires guests to dress in formal attire.","t":"正式晚宴要求客人穿著正式服裝。"},{"w":"former","p":"adj.","d":"earlier; from the past","c":"前者的","s":"The former is preferred over the latter in most cases.","t":"在大多數情況下，前者比後者更受歡迎。"},{"w":"inherent","p":"adj.","d":"being a natural part of something","c":"固有的","s":"There are inherent risks involved in the procedure.","t":"該過程涉及固有的風險。"},{"w":"inheritance","p":"n.","d":"money or property received after someone dies","c":"繼承","s":"The legal battle over the inheritance lasted for years.","t":"關於繼承的法律戰爭持續了好幾年。"},{"w":"hereditary disease","p":"n.","d":"an illness passed from parents to children","c":"遺傳病","s":"Early detection can help manage hereditary disease and improve quality of life.","t":"早期檢測可以幫助管理遺傳病並提高生活質量。"},{"w":"insight","p":"n.","d":"a clear and deep understanding","c":"洞察力","s":"His insight into human behavior is remarkable.","t":"他對人類行為的洞察力非常出色。"},{"w":"integral","p":"adj.","d":"necessary and important as part of a whole","c":"不可或缺的","s":"An integral part of the project is the collaboration between teams.","t":"該項目的一個不可或缺的部分是團隊之間的合作。"},{"w":"integrate","p":"v.","d":"to combine things to work together","c":"整合","s":"The goal is to integrate all the systems for better functionality.","t":"目標是整合所有系統以實現更好的功能。"},{"w":"integrated","p":"adj.","d":"combined into one system","c":"綜合的","s":"The integrated approach yielded better results in tackling the issue.","t":"綜合方法在解決問題方面取得了更好的效果。"},{"w":"integration","p":"n.","d":"the act of combining things","c":"整合","s":"integration of data from different sources can be challenging.","t":"從不同來源整合數據可能具有挑戰性。"},{"w":"intermediate","p":"adj.","d":"between beginning and advanced","c":"中等的","s":"The course is designed for intermediate level learners.","t":"該課程是為中等水平的學習者設計的。"},{"w":"manual","p":"adj.","d":"done by hand","c":"手動的","s":"In the absence of power, the manual override can be used to operate the system.","t":"在缺乏電力的情況下，可以使用手動覆蓋來操作系統。"},{"w":"manual","p":"n.","d":"a book of instructions","c":"手冊","s":"Please refer to the manual for troubleshooting tips.","t":"請參閱手冊以獲取疑難解答技巧。"},{"w":"mature","p":"v.","d":"to grow and develop fully","c":"成熟","s":"It will take some time for the idea to mature and become viable.","t":"該想法需要一些時間才能成熟並變得可行。"},{"w":"mature","p":"adj.","d":"fully grown; behaving like an adult","c":"成熟的","s":"She is very mature for her age and handles situations well.","t":"她非常成熟，能夠很好地處理情況。"},{"w":"immature","p":"adj.","d":"behaving like a child","c":"不成熟的","s":"His immature behavior was frowned upon by his peers.","t":"他不成熟的行為受到了同伴的不滿。"},{"w":"maturity","p":"n.","d":"the state of being fully grown","c":"成熟度","s":"His maturity and professionalism are admired by everyone in the office.","t":"他在辦公室裡的成熟度和專業度受到每個人的欣賞。"},{"w":"immaturity","p":"n.","d":"childish behavior","c":"不成熟","s":"Her immaturity was evident when she threw a tantrum over a minor issue.","t":"她因為一個小問題發脾氣，顯示出她的不成熟。"},{"w":"mediate","p":"v.","d":"to help two sides agree","c":"調解","s":"The counselor tried to mediate the dispute between the two parties.","t":"輔導員試圖調解兩方的爭端。"}]},{"unit":6,"theme":"mediation – qualitative research","cards":[{"w":"mediation","p":"n.","d":"help given to two sides to agree","c":"調解","s":"They agreed to settle the matter through mediation.","t":"他們同意通過調解解決這個問題。"},{"w":"medium","p":"n.","d":"a way of sending information","c":"媒介","s":"Television is a powerful medium for advertising.","t":"電視是一個強大的廣告媒介。"},{"w":"media","p":"n.","d":"TV, radio, newspapers and the internet","c":"媒體","s":"The media plays a crucial role in shaping public opinion.","t":"媒體在塑造公眾輿論中起著關鍵作用。"},{"w":"military","p":"n./adj.","d":"about the army; the armed forces","c":"軍事/軍方的","s":"He joined the military after graduating from high school.","t":"他高中畢業後加入了軍隊。"},{"w":"militant","p":"adj.","d":"ready to fight for a cause","c":"好戰的","s":"The group has adopted a more militant stance in recent years.","t":"該組織近年來采取了更為好戰的立場。"},{"w":"minimal","p":"adj.","d":"very small in amount","c":"最小的","s":"The project was completed with minimal resources.","t":"該項目以最少的資源完成。"},{"w":"mutual","p":"adj.","d":"shared by two or more people","c":"相互的","s":"It was a mutual decision made by both parties involved.","t":"這是由涉及的雙方作出的相互決定。"},{"w":"norms","p":"n.","d":"usual ways of behaving in a group","c":"常規","s":"The norms of the community were strictly adhered to by all members.","t":"社區的常規被所有成員嚴格遵守。"},{"w":"overlap","p":"v.","d":"to cover part of the same area","c":"重疊","s":"The two projects overlap in terms of objectives and resources.","t":"這兩個項目在目標和資源方面存在重疊。"},{"w":"overlapping","p":"adj.","d":"partly covering the same area","c":"重疊的","s":"Due to the overlapping deadlines, the team had to prioritize tasks.","t":"由於截止日期的重疊，團隊不得不對任務進行優先排序。"},{"w":"passive","p":"adj.","d":"letting things happen without taking action","c":"被動的","s":"In a passive role, he didn't contribute much to the discussion.","t":"在被動的角色中，他對討論沒有做出太多貢獻。"},{"w":"active","p":"adj.","d":"busy doing things; taking action","c":"積極的","s":"Taking an active role in community service is very rewarding.","t":"在社區服務中擔任積極角色非常有益。"},{"w":"portion","p":"n.","d":"a part of something","c":"部分","s":"A significant portion of the budget was allocated to marketing.","t":"預算的一大部分分配給了市場營銷。"},{"w":"proportion","p":"n.","d":"the amount of one thing compared to another","c":"比例","s":"The proportion of funding for each department was carefully calculated.","t":"每個部門的資金比例都經過精心計算。"},{"w":"disproportionate","p":"adj.","d":"too large or too small compared to something","c":"不成比例的","s":"The disproportionate amount of attention given to the issue was not justified.","t":"給予該問題的關注不成比例，這是不合理的。"},{"w":"preliminary","p":"adj.","d":"done first to prepare for something","c":"初步的","s":"preliminary data indicates a positive trend in sales.","t":"初步數據顯示銷售呈現出積極的趨勢。"},{"w":"protocol","p":"n.","d":"an official set of rules","c":"協議","s":"Following the correct protocol is crucial for ensuring network security.","t":"遵循正確的協議對於確保網絡安全至關重要。"},{"w":"prototype","p":"n.","d":"the first model of something","c":"原型","s":"The prototype of the machine was created to test the design before mass production.","t":"機器的原型是為了在大規模生產之前測試設計而創建的。"},{"w":"quality","p":"n.","d":"how good or bad something is","c":"質量","s":"The quality of the product is ensured through rigorous testing.","t":"通過嚴格的測試來確保產品的質量。"},{"w":"qualitative research","p":"n.","d":"research about people's opinions and experiences","c":"定性研究","s":"qualitative research provides in-depth insights into human behavior.","t":"定性研究為人類行為提供了深刻的見解。"}]},{"unit":7,"theme":"quantity – scenery","cards":[{"w":"quantity","p":"n.","d":"an amount or number","c":"數量","s":"The quantity of goods available will meet the demand.","t":"可用商品的數量將滿足需求。"},{"w":"quantitative research","p":"n.","d":"research using numbers and data","c":"定量研究","s":"quantitative research relies on statistical analysis to draw conclusions.","t":"定量研究依賴統計分析來得出結論。"},{"w":"refine","p":"v.","d":"to make something purer or better","c":"精煉","s":"They plan to refine the process to improve efficiency.","t":"他們計劃精煉該過程以提高效率。"},{"w":"refined","p":"adj.","d":"made purer or better","c":"精煉的","s":"The refined product is free from impurities.","t":"精煉的產品不含雜質。"},{"w":"refinement","p":"n.","d":"a small change that improves something","c":"精煉","s":"The refinement of the system led to significant performance improvements.","t":"系統的精煉導致性能得到了顯著改善。"},{"w":"relax","p":"v.","d":"to rest and feel calm","c":"放鬆","s":"It's important to relax and reduce stress for overall well-being.","t":"為了整體健康，放鬆和減壓很重要。"},{"w":"relaxing","p":"adj.","d":"making you feel calm","c":"放鬆的","s":"A relaxing vacation by the beach helped her recharge.","t":"在海灘上度過一個放鬆的假期幫助她重新充電。"},{"w":"relaxed","p":"adj.","d":"feeling calm","c":"放鬆的","s":"After a long week of work, he felt relaxed on the weekend getaway.","t":"經過一周的辛勤工作，他在周末度假時感到很放鬆。"},{"w":"relaxation","p":"n.","d":"rest and enjoyment","c":"放鬆","s":"relaxation techniques such as deep breathing and meditation can help manage stress.","t":"如深呼吸和冥想等放鬆技術可以幫助緩解壓力。"},{"w":"restrain","p":"v.","d":"to stop someone from doing something","c":"抑制","s":"She had to restrain her anger during the heated argument.","t":"在激烈的爭論中，她不得不抑制她的憤怒。"},{"w":"restraint","p":"n.","d":"control over your feelings or actions","c":"克制","s":"Showing restraint in difficult situations is a sign of maturity.","t":"在困難的情況下表現出克制是成熟的表現。"},{"w":"revolve","p":"v.","d":"to turn around a center point","c":"旋轉","s":"The earth revolve around the sun.","t":"地球繞太陽旋轉。"},{"w":"revolving","p":"adj.","d":"turning around a center point","c":"旋轉的","s":"The revolving door at the entrance was a modern touch to the building.","t":"入口處的旋轉門為建築增添了現代感。"},{"w":"revolution","p":"n.","d":"a big change in government or society","c":"革命","s":"The industrial revolution dramatically changed the way people lived and worked.","t":"工業革命戲劇性地改變了人們的生活和工作方式。"},{"w":"rigid","p":"adj.","d":"not able to bend or change","c":"僵硬的","s":"The rigid structure of the organization left little room for creativity.","t":"組織的僵硬結構留下了很小的創造空間。"},{"w":"rigidity","p":"n.","d":"the quality of not being able to change","c":"僵硬","s":"The rigidity of the system made it difficult to implement changes.","t":"系統的僵硬使得很難實施變更。"},{"w":"route","p":"n.","d":"the way you go from one place to another","c":"路線","s":"They decided to take a scenic route through the countryside.","t":"他們決定選擇一條通過鄉村的風景路線。"},{"w":"scene","p":"n.","d":"the place where something happens","c":"現場","s":"The scene of the accident was cordoned off for investigation.","t":"事故現場被封鎖以進行調查。"},{"w":"scenario","p":"n.","d":"a possible situation in the future","c":"情景","s":"The training exercise simulated a scenario of a large-scale emergency.","t":"訓練練習模擬了大規模緊急情況的情景。"},{"w":"scenery","p":"n.","d":"the natural beauty of a place","c":"風景","s":"The scenery along the coast was breathtaking.","t":"沿海的風景令人屏息。"}]},{"unit":8,"theme":"scenic – trigger","cards":[{"w":"scenic","p":"adj.","d":"having beautiful natural views","c":"風景優美的","s":"The scenic route provided many photo opportunities.","t":"風景優美的路線提供了許多拍照機會。"},{"w":"sphere","p":"n.","d":"a round shape like a ball","c":"球體","s":"The sphere had a diameter of 10 inches.","t":"球體的直徑為10英寸。"},{"w":"spherical","p":"adj.","d":"shaped like a ball","c":"球形的","s":"The spherical object rolled down the hill.","t":"球形的對象沿著山坡滾下。"},{"w":"subordinate","p":"n./adj.","d":"a person with a lower position at work","c":"下屬/下級的","s":"He treated his subordinate with respect and fairness.","t":"他尊重並公平地對待他的下屬。"},{"w":"supplementary","p":"adj.","d":"added to make something complete","c":"補充的","s":"The supplementary materials provided additional information on the topic.","t":"補充材料提供了有關該主題的額外信息。"},{"w":"suspend","p":"v.","d":"to stop something for a short time","c":"暫停","s":"They had to suspend the construction work due to bad weather.","t":"由於惡劣天氣，他們不得不暫停施工工作。"},{"w":"suspended","p":"adj.","d":"stopped for a short time","c":"被暫停的","s":"The suspended student reflected on his actions during the disciplinary period.","t":"被暫停的學生在紀律期間反思了他的行為。"},{"w":"suspense","p":"n.","d":"a feeling of excitement about what will happen","c":"懸念","s":"The movie kept the audience in suspense until the very end.","t":"這部電影讓觀眾直到最後都感到懸念不已。"},{"w":"suspension","p":"n.","d":"the act of hanging something","c":"懸掛","s":"The bridge's suspension system was an architectural marvel.","t":"這座橋的懸掛系統是建築奇蹟。"},{"w":"team","p":"v.","d":"to work together in a group","c":"組隊","s":"They decided to team up for the project to utilize each other's strengths.","t":"他們決定為了利用彼此的優勢而組隊完成該項目。"},{"w":"team","p":"n.","d":"a group of people working together","c":"團隊","s":"The team worked tirelessly to meet the deadline.","t":"團隊不知疲倦地工作以趕上截止日期。"},{"w":"permanent","p":"adj.","d":"lasting forever","c":"永久的","s":"The decision will have a permanent impact on the community.","t":"該決定將對社區產生永久性影響。"},{"w":"permanently","p":"adv.","d":"forever","c":"永久地","s":"The old building was permanently closed due to safety concerns.","t":"由於安全考慮，舊建築被永久關閉。"},{"w":"temporary","p":"adj.","d":"lasting only for a short time","c":"臨時的","s":"The company hired temporary workers during the busy season.","t":"公司在繁忙季節聘用了臨時工。"},{"w":"temporarily","p":"adv.","d":"for a short time","c":"臨時地","s":"The road was temporarily closed for construction.","t":"道路因施工臨時關閉。"},{"w":"contemporary","p":"adj./n.","d":"modern; living at the same time","c":"當代的/同時代的人","s":"The artist was influenced by many of his contemporary.","t":"這位藝術家受到了許多他的同時代人的影響。"},{"w":"temperate","p":"adj.","d":"not too hot or too cold","c":"溫和的","s":"The region has a temperate climate, which is ideal for agriculture.","t":"該地區有溫和的氣候，非常適合農業。"},{"w":"temperature","p":"n.","d":"how hot or cold something is","c":"溫度","s":"The temperature dropped significantly overnight, signaling the onset of winter.","t":"溫度在一夜之間顯著下降，標誌著冬季的來臨。"},{"w":"trigger","p":"n.","d":"something that causes a reaction","c":"觸發器","s":"The trigger mechanism was highly sensitive to any movement.","t":"觸發機制對任何移動都非常敏感。"},{"w":"trigger","p":"v.","d":"to cause something to start","c":"觸發","s":"Unexpected events can trigger a chain reaction.","t":"意外事件可能會觸發連鎖反應。"}]},{"unit":9,"theme":"unify – volunteer","cards":[{"w":"unify","p":"v.","d":"to join things together into one","c":"統一","s":"The leader aimed to unify the various factions under a common goal.","t":"領導者旨在統一各派系以實現共同的目標。"},{"w":"unified","p":"adj.","d":"joined into one","c":"統一的","s":"A unified approach was adopted to tackle the complex issue.","t":"採用了統一的方法來解決複雜的問題。"},{"w":"unite","p":"v.","d":"to join together","c":"團結","s":"They decided to unite their efforts to achieve the objective.","t":"他們決定團結起來努力實現目標。"},{"w":"united","p":"adj.","d":"joined together as one","c":"團結的","s":"The united team worked harmoniously towards success.","t":"團結的團隊和諧地朝成功努力。"},{"w":"uniform","p":"adj./n.","d":"the same; a special set of clothes","c":"統一的/制服","s":"All members of the organization wore a uniform to represent unity.","t":"組織的所有成員都穿著制服以表示團結。"},{"w":"violate","p":"v.","d":"to break a law or rule","c":"違反","s":"To violate the law will result in penalties.","t":"違反法律將導致處罰。"},{"w":"violation","p":"n.","d":"the act of breaking a law or rule","c":"違反","s":"The violation of privacy is a serious offense.","t":"侵犯隱私是嚴重的犯罪。"},{"w":"vision","p":"n.","d":"a picture of the future you hope for","c":"視覺","s":"His vision for the company's future included expanding into new markets.","t":"他對公司未來的視覺包括擴展到新市場。"},{"w":"vision","p":"v.","d":"to imagine a picture of the future","c":"設想","s":"He vision a world where clean energy would be accessible to all.","t":"他設想一個清潔能源對所有人都可訪問的世界。"},{"w":"visual","p":"adj.","d":"about seeing","c":"視覺的","s":"visual aids can significantly enhance the learning experience.","t":"視覺輔助工具可以顯著增強學習體驗。"},{"w":"visualize","p":"v.","d":"to form a picture in your mind","c":"可視化","s":"It's easier to understand complex data when you visualize it with graphs and charts.","t":"當您用圖表和圖表可視化它時，更容易理解複雜的數據。"},{"w":"widespread","p":"adj.","d":"found in many places","c":"廣泛的","s":"The widespread adoption of smartphones has changed the way we communicate.","t":"智能手機的廣泛采用改變了我們的交流方式。"},{"w":"visual","p":"adj.","d":"about seeing","c":"視覺的","s":"There was a visual appeal in the design that attracted many customers.","t":"設計中有一種視覺吸引力，吸引了許多客戶。"},{"w":"voluntary","p":"adj.","d":"done because you want to","c":"自願的","s":"They offered voluntary services to help the community after the natural disaster.","t":"自然災害後，他們提供自願服務來幫助社區。"},{"w":"volunteer","p":"v.","d":"to offer to do something without being paid","c":"自願","s":"Many people chose to volunteer at local shelters.","t":"許多人選擇在當地的庇護所自願。"},{"w":"volunteer","p":"n.","d":"a person who works without being paid","c":"志願者","s":"The volunteer dedicated their time and effort to help others.","t":"志願者奉獻了他們的時間和精力來幫助他人。"}]}];
